 "water-cooled-chiller":{ general:"As for chillers, with a condenser-water loop to a cooling tower or dry cooler. Confirm condenser-water temperatures, tower selection, and water treatment.", conditional:[{when:"Cooling tower used",what:"Legionella risk management (ASHRAE 188) and water treatment apply."}], refs:["imc","ashrae-901","ashrae-15","ashrae-188","ahri"], checklist:["Confirm condenser-water temperatures and tower selection","Confirm water treatment and Legionella provisions"], coordination:["Plumbing/water treatment","Electrical"], missing:["Condenser-water source","Water quality"] },
 "dx-system":{ general:"Direct-expansion system: refrigerant circuit between indoor and outdoor units. Confirm capacity, refrigerant type and charge, piping lengths and lifts, and ASHRAE 15 safety provisions for the refrigerant and occupancy.", conditional:[{when:"Large charge or occupied space",what:"ASHRAE 15 charge limits, leak detection, and ventilation may apply — confirm the refrigerant and charge."}], refs:["ashrae-15","ashrae-34","asme-b315","imc"], checklist:["Confirm refrigerant type, charge, and safety classification","Confirm piping lengths, lifts, and oil return","Confirm leak detection where required"], coordination:["Electrical","Architecture (unit locations)"], missing:["Refrigerant type and charge","Piping route and length"] },
 crac:{ general:"Computer-room air conditioner: precision cooling for IT spaces. Confirm sensible capacity (not just total), airflow, supply/return arrangement, and redundancy. DX CRAC needs refrigerant piping; chilled-water CRAC/CRAH needs chilled-water piping — the two are not interchangeable.", conditional:[{when:"DX CRAC",what:"Refrigerant piping per ASME B31.5 and ASHRAE 15 apply."},{when:"Chilled-water CRAC / CRAH",what:"Chilled-water piping per ASME B31.9, with isolation and leak detection, applies."},{when:"Installed in a data hall",what:"Select the data-hall space type for redundancy, environmental class, and fire-protection requirements."}], refs:["ashrae-tc99","ashrae-904","ashrae-15","asme-b315","asme-b319","nfpa-75"], checklist:["Confirm sensible vs total capacity","Confirm DX vs chilled-water configuration","Confirm airflow management and redundancy","Confirm leak detection and alarming"], coordination:["Electrical (UPS)","Fire protection","IT operations"], missing:["DX or chilled-water configuration","IT load and redundancy"] },
 crah:{ general:"As for CRAC, chilled-water based: confirm chilled-water temperatures and flows, airflow, redundancy, and leak detection.", conditional:[{when:"Installed in a data hall",what:"Select the data-hall space type for redundancy and environmental requirements."}], refs:["ashrae-tc99","ashrae-904","asme-b319","nfpa-75"], checklist:["Confirm chilled-water temperatures and flows","Confirm airflow and redundancy","Confirm leak detection"], coordination:["Electrical","Fire protection","IT operations"], missing:["Chilled-water temperatures","Redundancy"] },
 "cooling-tower":{ general:"Select by heat rejection, approach, range, water flow, and ambient wet-bulb. Provide basin, make-up, blowdown, water treatment, freeze protection, access, and Legionella risk management. Confirm structural loading, noise, drift, and plume.", conditional:[{when:"Healthcare or occupied building nearby",what:"Legionella risk management and drift control are more sensitive — confirm the water-management plan."}], refs:["ashrae-188","cti","imc","ashrae-901"], checklist:["Confirm heat rejection, approach, and range","Confirm water treatment and Legionella provisions (ASHRAE 188)","Confirm freeze protection, access, and maintenance","Confirm noise, drift, and plume assessment"], coordination:["Structural","Plumbing/water treatment","Acoustics"], missing:["Heat rejection and ambient wet-bulb","Water quality"] },
 "refrigerant-piping":{ general:"Design per ASME B31.5 and ASHRAE 15: pipe sizing for pressure drop and oil return, materials, joints, insulation, supports, and testing. Confirm refrigerant type, charge limits, and leak detection for the occupancy.", conditional:[{when:"Large charge",what:"ASHRAE 15 machinery-room, detection, and ventilation provisions may be triggered."}], refs:["asme-b315","ashrae-15","ashrae-34","imc"], checklist:["Confirm refrigerant, charge, and safety classification","Confirm pipe sizing, oil return, and insulation","Confirm pressure testing and leak detection"], coordination:["Architecture (routing)","Fire protection"], missing:["Refrigerant type and charge","Piping route"] },
 "refrigerant-leak":{ general:"Provide leak detection per ASHRAE 15 where the refrigerant, charge, or occupancy triggers it: sensors, alarming, and emergency ventilation for machinery rooms.", conditional:[{when:"Machinery room",what:"Detection, alarming, and emergency ventilation are normally required — confirm the ASHRAE 15 triggers."}], refs:["ashrae-15","ashrae-34"], checklist:["Confirm whether detection is triggered","Confirm sensor locations, alarming, and ventilation interlocks"], coordination:["Electrical","Controls/BMS"], missing:["Refrigerant and charge"] },
