 vav:{ general:"Variable-air-volume system: confirm zone loads, minimum airflows, reheat, controls, and commissioning. Confirm turndown and ventilation at minimum flow.", conditional:[{when:"Laboratory or healthcare",what:"Minimum airflows are often constrained by ventilation/pressure requirements — select the space types."}], refs:["ashrae-621","ashrae-901","ashrae-g36"], checklist:["Confirm zone loads and minimum airflows","Confirm reheat and controls","Confirm ventilation at minimum flow"], coordination:["Controls/BMS","Electrical"], missing:["Zone loads","Minimum-airflow basis"] },
