 ductwork:{ general:"Design per SMACNA: duct sizing, pressure class, sealing/leakage class, materials, supports, and access. Provide fire and smoke dampers where required by NFPA 90A and the adopted code.", conditional:[{when:"Fire-rated penetrations",what:"Fire/smoke dampers and penetration sealing per NFPA 90A apply."},{when:"Laboratory exhaust",what:"Duct material and corrosion resistance per ANSI/AIHA Z9.5 / NFPA 91 apply."}], refs:["smacna","nfpa-90a","imc","nfpa-91"], checklist:["Confirm duct pressure class and leakage class","Confirm damper locations and ratings","Confirm access doors and cleaning provisions"], coordination:["Structural","Fire protection","Architecture"], missing:["System type","Fire-rating of penetrations"] },
 damper:{ general:"Select fire dampers, smoke dampers, and combination fire/smoke dampers by rating, location, and actuation. Confirm access, testing, and BMS monitoring where required.", conditional:[{when:"Smoke control system",what:"Dampers are part of the smoke-control sequence — coordinate with NFPA 92."}], refs:["nfpa-90a","nfpa-92","imc"], checklist:["Confirm damper type and rating at each penetration","Confirm access and testing provisions","Confirm BMS monitoring"], coordination:["Fire protection","Controls/BMS"], missing:["Penetration fire ratings"] },
 boiler:{ general:"Select by capacity, efficiency, fuel, and operating temperatures/pressures. Confirm flue/venting, combustion air, gas piping, safety controls, and ASME BPVC applicability.", conditional:[{when:"Gas-fired",what:"Fuel-gas piping per the IFGC and combustion air per the IMC apply."}], refs:["imc","ifgc","asme-bpvc","ashrae-901"], checklist:["Confirm capacity, efficiency, and fuel","Confirm flue, combustion air, and gas piping","Confirm safety controls and commissioning"], coordination:["Gas/plumbing","Electrical","Structural","Fire protection"], missing:["Fuel and capacity","Flue route"] },
