 "chw-pump":{ general:"Select by flow, head, efficiency, and NPSH. Confirm duty/standby, VFD control, isolation, and commissioning.", conditional:[{when:"Primary/secondary or variable primary",what:"Confirm the pumping arrangement and control sequence."}], refs:["asme-b319","hi-pump","imc"], checklist:["Confirm flow, head, and NPSH","Confirm duty/standby and VFDs","Confirm isolation and commissioning"], coordination:["Electrical","Controls/BMS"], missing:["Flow and head","Pumping arrangement"] },
