 "cdu":{ general:"A cooling distribution unit (CDU) transfers heat between the Technology Cooling System (TCS) serving the IT equipment and the Facility Water System (FWS) for heat rejection. Confirm CDU capacity, flow, approach temperatures, pressure drops, leak detection, and the TCS/FWS interface. ASHRAE 127 Addendum b (2026) adds rating methods for CDUs.", conditional:[{when:"TCS vs FWS",what:"Treat the technology cooling system and the facility water system as separate systems — different water quality, pressures and materials; do not merge them into one loop."}], refs:["ashrae-127","ashrae-tc99","ashrae-tc99-thermal","ashrae-904"], checklist:["Confirm TCS/FWS split and interface temperatures","Confirm CDU capacity, flow and approach temperature","Confirm water quality (conductivity, pH, corrosion, biological control)","Confirm leak detection and isolation","Confirm redundancy and maintenance bypass"], coordination:["IT operations","Electrical","Fire protection"], missing:["CDU vendor data","TCS/FWS design temperatures","Water quality requirements"] },
